// ATOM2_01 · Validar e deduplicar (Code node, "Run Once for All Items").
// Fonte: ATOM2_ESPECIFICACAO.md, seções 5.1 e 5.2. Edite aqui e recole no nó.
const lote = $('Lote').first().json;
const cfgRows = $('Ler configuração').all().map((i) => i.json);
const baseRows = $('Ler base').all().map((i) => i.json).filter((r) => r && r.company_id);

const cfg = {};
for (const r of cfgRows) {
  if (r && r.chave) cfg[String(r.chave).trim()] = { valor: String(r.valor ?? '').trim(), status: String(r.status ?? '').trim().toUpperCase() };
}
const cfgValor = (k, padrao) => (cfg[k] && cfg[k].status === 'CONFIGURADO' && cfg[k].valor && !/^PENDENTE/i.test(cfg[k].valor) ? cfg[k].valor : padrao);
const verticais = cfgValor('VERTICAIS_PERMITIDAS', 'dental,medical').split(',').map((s) => s.trim()).filter(Boolean);
const exigirDominio = cfgValor('EXIGIR_DOMINIO', 'SIM').toUpperCase() !== 'NAO';
const FLUXOS = ['clinicas', 'sites'];

const UFS = ['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
const GENERICAS = ['clinica','clinicas','odontologia','odontologica','odontologico','odonto','consultorio','centro','instituto','medica','medico','medicos','medicina','saude','ltda','me','eireli','epp','ss','dr','dra','de','da','do','das','dos','e','&'];
const NAO_SITE = ['instagram.com','facebook.com','fb.com','wa.me','api.whatsapp.com','whatsapp.com','linktr.ee','google.com','goo.gl','g.page','maps.app.goo.gl','doctoralia.com.br','tiktok.com','youtube.com','linkedin.com'];
const ALIAS_VERTICAL = { dental: 'dental', odontologia: 'dental', odonto: 'dental', dentista: 'dental', odontologica: 'dental', medical: 'medical', medica: 'medical', medico: 'medical', medicina: 'medical', 'clinica medica': 'medical' };

const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
const limpo = (s) => semAcento(s).replace(/[^a-z0-9& ]/g, ' ').replace(/\s+/g, ' ').trim();
const texto = (v) => (v === null || v === undefined ? '' : String(v).trim());

function nomeNorm(nome) {
  // Nome só com palavras genéricas (ex.: "OdontoLógica") usa o nome inteiro, para não gerar chave fraca vazia.
  return limpo(nome).split(' ').filter((p) => p && !GENERICAS.includes(p)).join(' ') || limpo(nome);
}
function dominioDe(site) {
  const m = /^(?:[a-z][a-z0-9+.-]*:\/\/)?([^/?#\s]+)/i.exec(texto(site));
  if (!m) return '';
  const host = m[1].toLowerCase().replace(/:\d+$/, '').replace(/^www\./, '').replace(/\.$/, '');
  return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host) && !/^\d+(\.\d+){3}$/.test(host) ? host : '';
}
function ehNaoSite(dominio) {
  return NAO_SITE.some((d) => dominio === d || dominio.endsWith('.' + d));
}
function instagramDe(v, siteOriginal) {
  let s = texto(v);
  if (!s) {
    const m = /instagram\.com\/([^/?#\s]+)/i.exec(texto(siteOriginal));
    s = m ? m[1] : '';
  }
  s = s.replace(/^https?:\/\/(www\.)?instagram\.com\//i, '').replace(/^@/, '').replace(/[/?#].*$/, '').toLowerCase();
  return /^[a-z0-9._]{1,30}$/.test(s) ? s : '';
}
function telefoneDe(v) {
  let d = texto(v).replace(/\D/g, '');
  if (!d) return { valor: '', aviso: '' };
  // Já com DDI 55 (12–13 dígitos) não recebe outro 55; sem DDI (10–11 dígitos) recebe. DDD 11–99; celular (11 dígitos) começa com 9.
  if (!(d.startsWith('55') && (d.length === 12 || d.length === 13)) && (d.length === 10 || d.length === 11)) d = '55' + d;
  const nac = d.slice(2);
  const ok = /^55\d{10,11}$/.test(d) && Number(nac.slice(0, 2)) >= 11 && (nac.length === 10 || nac[2] === '9');
  if (!ok) return { valor: '', aviso: 'telefone inválido descartado: ' + texto(v) };
  return { valor: d, aviso: '' };
}
function dataISO(v) {
  const s = texto(v);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(s + 'T00:00:00Z');
  if (isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s) return null;
  return s;
}
function hash(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const agora = new Date().toISOString();
const hoje = agora.slice(0, 10);
const loteId = texto(lote.lote_id) || 'LOTE-' + agora.replace(/[-:T]/g, '').slice(0, 12);
const entrada = Array.isArray(lote.empresas) ? lote.empresas : [];

// Índices da base existente + o que já foi aceito neste lote.
const idx = { dominio: new Map(), place: new Map(), insta: new Map(), fraca: new Map() };
function indexar(r) {
  if (r.dominio) {
    if (!idx.dominio.has(r.dominio)) idx.dominio.set(r.dominio, []);
    idx.dominio.get(r.dominio).push(r);
  }
  if (r.place_id) idx.place.set(r.place_id, r);
  if (r.instagram) idx.insta.set(r.instagram, r);
  if (r.chave_fraca) {
    if (!idx.fraca.has(r.chave_fraca)) idx.fraca.set(r.chave_fraca, []);
    idx.fraca.get(r.chave_fraca).push(r);
  }
}
baseRows.forEach(indexar);

const saida = [];
const resumo = { lote_id: loteId, recebidas: entrada.length, gravadas: 0, revisao: 0, duplicadas: 0, invalidas: 0 };

entrada.forEach((bruto, i) => {
  const e = bruto && typeof bruto === 'object' ? bruto : {};
  const erros = [];
  const avisos = [];

  const nome = texto(e.nome);
  if (nome.length < 2 || nome.length > 120) erros.push('nome ausente ou fora de 2–120 caracteres');

  const vRaw = limpo(e.vertical);
  const vertical = ALIAS_VERTICAL[vRaw] || '';
  if (!vertical) erros.push('vertical desconhecida: ' + texto(e.vertical));
  else if (!verticais.includes(vertical)) erros.push('vertical fora do piloto: ' + vertical);

  const cidade = texto(e.cidade);
  if (cidade.length < 2 || cidade.length > 80) erros.push('cidade ausente');
  const uf = texto(e.uf).toUpperCase();
  if (!UFS.includes(uf)) erros.push('UF inválida: ' + texto(e.uf));

  const fonteUrl = texto(e.fonte_url);
  if (!/^https?:\/\/\S+\.\S+/i.test(fonteUrl)) erros.push('fonte_url ausente ou inválida');
  const fonteData = dataISO(e.fonte_data);
  if (!fonteData) erros.push('fonte_data ausente ou inválida (use AAAA-MM-DD)');
  else if (fonteData > hoje) erros.push('fonte_data no futuro');

  let dominio = dominioDe(e.site);
  if (dominio && ehNaoSite(dominio)) {
    avisos.push('site informado é rede social/agregador, não site próprio: ' + dominio);
    dominio = '';
  } else if (texto(e.site) && !dominio) {
    avisos.push('site inválido descartado: ' + texto(e.site));
  }
  const placeId = texto(e.place_id);
  const instagram = instagramDe(e.instagram, e.site);
  if (exigirDominio && !dominio) erros.push('sem domínio oficial (Playbook Operacional §2)');
  else if (!dominio && !placeId && !instagram) erros.push('sem identificador: informe site próprio, place_id ou instagram');

  const fluxoRaw = limpo(e.fluxo);
  const fluxo = fluxoRaw ? fluxoRaw : 'clinicas';
  if (!FLUXOS.includes(fluxo)) erros.push('fluxo inválido: ' + texto(e.fluxo) + ' (use clinicas ou sites)');

  const tel = telefoneDe(e.telefone);
  const wpp = telefoneDe(e.whatsapp);
  if (tel.aviso) avisos.push(tel.aviso);
  if (wpp.aviso) avisos.push(wpp.aviso.replace('telefone', 'whatsapp'));

  let unidades = null;
  if (texto(e.unidades) !== '') {
    const u = Number(e.unidades);
    if (Number.isInteger(u) && u >= 1 && u <= 500) unidades = u;
    else avisos.push('unidades inválido descartado: ' + texto(e.unidades));
  }

  const ref = { posicao: i + 1, nome: nome || '(sem nome)' };

  if (erros.length) {
    resumo.invalidas += 1;
    saida.push({ json: { destino: 'evento', evento: { tipo: 'IMPORT_INVALIDA', motivo: erros.join('; '), company_id: '', dados: JSON.stringify({ ...ref, avisos, entrada: e }) } } });
    return;
  }

  const nn = nomeNorm(nome);
  const chaveFraca = [nn, limpo(cidade), uf].join('|');
  const chaveForte = dominio ? 'd:' + dominio : placeId ? 'p:' + placeId : 'i:' + instagram;
  const companyId = 'c_' + hash(chaveForte + '|' + limpo(cidade) + '|' + uf);

  let decisao = null;
  const mesmoPlace = placeId && idx.place.get(placeId);
  const mesmoInsta = instagram && idx.insta.get(instagram);
  const mesmoDominio = dominio ? idx.dominio.get(dominio) || [] : [];
  const mesmaCidade = mesmoDominio.find((r) => limpo(r.cidade) === limpo(cidade) && r.uf === uf);
  if (mesmoPlace) decisao = { tipo: 'DUPLICADA', motivo: 'mesmo place_id de ' + mesmoPlace.company_id, ref: mesmoPlace.company_id };
  else if (mesmaCidade) decisao = { tipo: 'DUPLICADA', motivo: 'mesmo domínio e cidade de ' + mesmaCidade.company_id, ref: mesmaCidade.company_id };
  else if (mesmoInsta) decisao = { tipo: 'DUPLICADA', motivo: 'mesmo instagram de ' + mesmoInsta.company_id, ref: mesmoInsta.company_id };
  else if (mesmoDominio.length) decisao = { tipo: 'POSSIVEL_FILIAL', motivo: 'mesmo domínio em outra cidade: ' + mesmoDominio.map((r) => r.company_id).join(', ') };
  else if (idx.fraca.has(chaveFraca)) decisao = { tipo: 'AMBIGUA', motivo: 'mesmo nome e cidade, identificador diferente: ' + idx.fraca.get(chaveFraca).map((r) => r.company_id).join(', ') };

  if (decisao && decisao.tipo === 'DUPLICADA') {
    resumo.duplicadas += 1;
    saida.push({ json: { destino: 'evento', evento: { tipo: 'IMPORT_DUPLICADA', motivo: decisao.motivo, company_id: decisao.ref, dados: JSON.stringify({ ...ref, avisos }) } } });
    return;
  }

  const revisao = Boolean(decisao);
  const linha = {
    company_id: companyId,
    nome,
    nome_norm: nn,
    razao_social: texto(e.razao_social),
    cnpj: texto(e.cnpj).replace(/[^0-9A-Za-z]/g, '').toUpperCase(),
    vertical,
    cidade,
    uf,
    bairro: texto(e.bairro),
    dominio,
    place_id: placeId,
    instagram,
    telefone: tel.valor,
    whatsapp: wpp.valor,
    unidades,
    fonte_url: fonteUrl,
    fonte_data: fonteData,
    chave_forte: chaveForte,
    chave_fraca: chaveFraca,
    status: revisao ? 'review_pending' : 'validated',
    funil_etapa: revisao ? 'F0' : 'F1',
    fluxo,
    company_status: texto(e.company_status),
    contact_channel: texto(e.contact_channel),
    contact_permission_status: texto(e.contact_permission_status) || 'nao_avaliado',
    owner: texto(e.owner),
    status_motivo: revisao ? decisao.tipo + ': ' + decisao.motivo : avisos.join('; '),
    score: null,
    faixa: '',
    score_versao: '',
    score_detalhe: '',
    lote_id: loteId,
    opt_out: false,
    pipedrive_org_id: '',
    pipedrive_lead_id: '',
    criado_em: agora,
    atualizado_em: agora,
  };
  indexar(linha);
  if (revisao) resumo.revisao += 1;
  else resumo.gravadas += 1;
  saida.push({ json: { destino: 'gravar', linha } });
  if (revisao) {
    saida.push({ json: { destino: 'evento', evento: { tipo: 'IMPORT_' + decisao.tipo, motivo: decisao.motivo, company_id: companyId, dados: JSON.stringify({ ...ref, avisos }) } } });
  }
});

// Cada evento recebe identificação e data; o resumo vai no último item.
saida.forEach((s, n) => {
  if (s.json.destino === 'evento') {
    s.json.evento = { event_id: loteId + '-' + String(n + 1).padStart(4, '0'), correlation_id: loteId, workflow: 'ATOM2_01', ocorrido_em: agora, ...s.json.evento };
  }
});
saida.push({ json: { destino: 'resumo', resumo } });
return saida;
